function tr(text:string,lang:string){return polishTranslations[lang]?.[text]||finalTranslations[lang]?.[text]||completeTranslations[lang]?.[text]||pageTranslations[lang]?.[text]||lastTranslations[lang]?.[text]||extendedTranslations[lang]?.[text]||translations[lang]?.[text]||text}

export default function Page(){const[view,setView]=useState<View>("Overview");const[crops,setCrops]=useState<Crop[]>(demoCrops);const[expenses,setExpenses]=useState<Expense[]>(demoExpenses);const[sales,setSales]=useState<Sale[]>(demoSales);const[notice,setNotice]=useState("");const[modal,setModal]=useState<"expense"|"crop"|"sale"|null>(null);const[query,setQuery]=useState("");const[voice,setVoice]=useState("");const[lang,setLang]=useState("English");const[weather,setWeather]=useState<any>(null);const[weatherErr,setWeatherErr]=useState("");const[loadingWeather,setLoadingWeather]=useState(false);const[sim,setSim]=useState({cropId:"soy",yieldKg:"900",price:"48",extra:"0",yieldDrop:"0",priceDrop:"0"});const[market,setMarket]=useState({crop:"Soybean",price:"",market:""});const[ef,setEf]=useState({cropId:"soy",amount:"",category:"Fertilizer",description:"",date:new Date().toISOString().slice(0,10)});const[cf,setCf]=useState({name:"",area:"1",budget:"20000",yieldKg:"500",price:"30",season:"Rabi 2026"});const[sf,setSf]=useState({cropId:"soy",quantity:"",price:""});useEffect(()=>{try{const x=localStorage.getItem("sm-data");if(x){const d=JSON.parse(x);setCrops(d.crops||demoCrops);setExpenses(d.expenses||demoExpenses);setSales(d.sales||demoSales)}}catch{}},[]);useEffect(()=>{try{localStorage.setItem("sm-data",JSON.stringify({crops,expenses,sales}))}catch{}},[crops,expenses,sales]);const tell=(s:string)=>{setNotice(s);setTimeout(()=>setNotice(""),3200)};const totalCost=expenses.reduce((s,e)=>s+e.amount,0),totalRevenue=sales.reduce((s,a)=>s+a.quantity*a.price,0);const filtered=useMemo(()=>expenses.filter(e=>(e.description+" "+e.category+" "+(crops.find(c=>c.id===e.cropId)?.name||"")).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date)),[expenses,crops,query]);function startVoice(){const S=(window as any).SpeechRecognition||(window as any).webkitSpeechRecognition;if(!S){tell("Speech recognition isn't supported here. Use the form below.");return}const r=new S();r.lang=lang==="Marathi"?"mr-IN":lang==="Hindi"?"hi-IN":"en-IN";r.onresult=(e:any)=>{const t=e.results[0][0].transcript;setVoice(t);const n=t.match(/(?:₹|rs\.?\s*)?([0-9][0-9,]*(?:\.\d+)?)/i);const lower=t.toLowerCase();const c=crops.find(c=>lower.includes(c.name.toLowerCase())||(c.id==="soy"&&(lower.includes("soyabean")||lower.includes("soybean")||lower.includes("सोयाबीन"))));const category=/khat|fertili|खत/.test(lower)?"Fertilizer":/seed|बियाणे|बीज/.test(lower)?"Seeds":/labour|majuri|मजुरी/.test(lower)?"Labour":"Other";setEf(f=>({...f,amount:n?n[1].replace(/,/g,""):"",description:t,cropId:c?.id||f.cropId,category}))};r.onerror=()=>tell("Could not recognize speech; please type instead.");r.start()};function saveExpense(){const a=Number(ef.amount);if(!ef.cropId||!Number.isFinite(a)||a<=0){tell(tr("Enter a valid amount and crop.",lang));return}setExpenses(p=>[{id:crypto.randomUUID(),...ef,amount:a,source:voice?"voice":"manual"},...p]);setModal(null);setVoice("");setEf(f=>({...f,amount:"",description:""}));tell(tr("Expense saved on this device.",lang))}function addCrop(){if(!cf.name.trim()||Number(cf.area)<=0||Number(cf.budget)<0){tell("Enter valid crop details.");return}const c:Crop={id:crypto.randomUUID(),name:cf.name,area:+cf.area,budget:+cf.budget,yieldKg:+cf.yieldKg,price:+cf.price,season:cf.season};setCrops(p=>[c,...p]);setEf(f=>({...f,cropId:c.id}));setModal(null);tell(tr("Crop cycle created.",lang))}function addSale(){if(+sf.quantity<=0||+sf.price<0){tell("Enter a valid quantity and price.");return}setSales(p=>[{id:crypto.randomUUID(),cropId:sf.cropId,quantity:+sf.quantity,price:+sf.price,date:new Date().toISOString().slice(0,10)},...p]);setModal(null);tell(tr("Sale recorded.",lang))}async function loadWeather(){setLoadingWeather(true);setWeatherErr("");try{const r=await fetch("https://api.open-meteo.com/v1/forecast?latitude=18.5204&longitude=73.8567&current=temperature_2m,relative_humidity_2m,apparent_temperature,precipitation,wind_speed_10m&daily=temperature_2m_max,temperature_2m_min,precipitation_probability_max,precipitation_sum&timezone=Asia%2FKolkata&forecast_days=5");if(!r.ok)throw Error();setWeather(await r.json())}catch{setWeatherErr("Weather provider unavailable. Check internet and retry.")}finally{setLoadingWeather(false)}}const cropCards=crops.map(c=>{const co=cost(c.id,expenses),rev=revenue(c.id,sales),pr=projection(c,expenses,sales);return <div className="card p-5" key={c.id}><div className="flex items-start justify-between gap-2"><div><h3 className="display text-lg font-extrabold">{tr(c.name,lang)}</h3><p className="muted mt-1 text-xs">{tr(c.season,lang)} · {c.area} {tr("acres",lang)}</p></div><span className="rounded-full bg-[#edf5e7] px-3 py-1 text-xs font-bold text-[#315b28]">{tr("Crop cycle",lang)}</span></div><div className="mt-4 grid grid-cols-2 gap-3"><div className="rounded-xl bg-[#f6f8f2] p-3"><div className="muted text-xs">{tr("Recorded expenses",lang)}</div><b className="mt-1 block">{money(co)}</b></div><div className="rounded-xl bg-[#f6f8f2] p-3"><div className="muted text-xs">{tr("Recorded sales",lang)}</div><b className="mt-1 block">{money(rev)}</b></div></div><div className="mt-4"><div className="muted text-xs">{tr("Estimated season result*",lang)}</div><div className="display mt-1 text-2xl font-extrabold">{money(pr)}</div></div><div className="mt-3 h-2 rounded-full bg-[#edf0e8]"><div className="h-2 rounded-full bg-[#79a85a]" style={{width:Math.min(100,co/Math.max(c.budget,1)*100)+"%"}}/></div><div className="muted mt-1 text-xs">{Math.round(co/Math.max(c.budget,1)*100)}% {tr("of budget spent",lang)}</div></div>});const table=<div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead className="muted border-b text-xs"><tr><th className="p-3">{tr("Expense",lang)}</th><th className="p-3">{tr("Crop",lang)}</th><th className="p-3">{tr("Date",lang)}</th><th className="p-3 text-right">{tr("Amount",lang)}</th><th className="p-3"> </th></tr></thead><tbody>{filtered.map(e=><tr key={e.id} className="border-b border-[#f0f2ed]"><td className="p-3"><b>{e.description}</b><div className="muted text-xs">{tr(e.category,lang)} · {tr(e.source,lang)}</div></td><td className="p-3">{crops.find(c=>c.id===e.cropId)?.name||"—"}</td><td className="p-3 text-xs">{e.date}</td><td className="p-3 text-right font-extrabold">{money(e.amount)}</td><td className="p-3"><button aria-label={tr("Delete expense",lang)} onClick={()=>{setExpenses(p=>p.filter(x=>x.id!==e.id));tell(tr("Expense deleted.",lang))}}><Trash2 size={15}/></button></td></tr>)}</tbody></table>{!filtered.length&&<p className="muted p-6 text-center">{tr("No expenses found.",lang)}</p>}</div>;
return <div className="layout min-h-screen md:flex"><aside className="side fixed left-0 top-0 z-20 flex h-screen w-[240px] flex-col border-r border-[#e5eadf] bg-white p-4"><div className="flex items-center gap-3 p-2"><div className="rounded-2xl bg-[#315b28] p-3 text-white"><Sprout size={24}/></div><div><div className="display font-extrabold">Shetkari<span className="text-[#5a8e35]">Mitra</span></div><div className="muted text-[10px] font-bold uppercase tracking-widest">{tr("Farm intelligence",lang)}</div></div></div><div className="label mb-2 mt-7 px-3">{tr("FARM WORKSPACE",lang)}</div><nav className="navs flex-1 space-y-1">{nav.map(n=><button className={"nav "+(view===n.name?"active":"")} key={n.name} onClick={()=>setView(n.name)}><n.icon size={17}/>{tr(n.name,lang)}</button>)}</nav><div className="rounded-2xl bg-[#f1f6eb] p-3"><b className="text-sm">{tr("Local demo mode",lang)}</b><p className="muted mt-1 text-xs leading-5">{tr("Data stays in this browser. Supabase cloud sync is not connected.",lang)}</p></div></aside><div className="content min-w-0 flex-1 md:ml-[240px]"><header className="sticky top-0 z-10 flex items-center justify-between border-b border-[#e5eadf] bg-[#f6f8f2]/90 px-4 py-4 backdrop-blur md:px-8"><div><div className="muted text-xs">{tr("Farm workspace",lang)} / {tr(view,lang)}</div><h1 className="display mt-1 text-xl font-extrabold">{view==="Overview"?tr("Good day, farmer 🌱",lang):tr(view,lang)}</h1></div><select className="input !w-auto !py-2 text-sm" value={lang} onChange={e=>setLang(e.target.value)}><option value="English">English</option><option value="Marathi">{tr("Marathi",lang)}</option><option value="Hindi">{tr("Hindi",lang)}</option></select></header><main className="mx-auto max-w-[1400px] p-4 md:p-8">{view==="Overview"&&<><section className="relative overflow-hidden rounded-[26px] bg-[#23451f] p-6 text-white md:p-8"><div className="grid gap-6 md:grid-cols-[1.2fr_.8fr] md:items-center"><div><span className="rounded-full border border-white/20 bg-white/10 px-3 py-1 text-xs font-bold text-[#d7f3be]">{tr("FARM INTELLIGENCE · MAHARASHTRA",lang)}</span><h2 className="display mt-5 max-w-xl text-3xl font-extrabold leading-tight md:text-4xl">{tr("Know where your money goes.",lang)} <span className="text-[#c8ee8d]">{tr("Act before a loss.",lang)}</span></h2><p className="mt-3 max-w-lg text-sm leading-6 text-white/75">{tr("A voice-first crop ledger and decision companion built around the way farmers work.",lang)}</p><div className="mt-5 flex flex-wrap gap-3"><button className="rounded-xl bg-[#d2f39a] px-4 py-3 text-sm font-extrabold text-[#23451f]" onClick={()=>{setView("Add Expense");setModal("expense")}}><Mic size={16} className="mr-2 inline"/>{tr("Record expense",lang)}</button><button className="rounded-xl border border-white/25 px-4 py-3 text-sm font-bold" onClick={()=>setView("Decision Simulator")}>{tr("Run a what-if",lang)} <ArrowRight size={15} className="ml-1 inline"/></button></div></div><div className="rounded-3xl border border-white/15 bg-white/[.08] p-5"><div className="text-xs text-white/60">{tr("SAMPLE SEASON · ESTIMATE",lang)}</div><div className="mt-3 text-sm text-white/70">{tr("Recorded sales minus recorded costs",lang)}</div><div className="display mt-1 text-4xl font-extrabold">{money(totalRevenue-totalCost)}</div><div className="mt-4 grid grid-cols-2 gap-3 border-t border-white/15 pt-4"><div><div className="text-xs text-white/60">{tr("Recorded costs",lang)}</div><b className="mt-1 block">{money(totalCost)}</b></div><div><div className="text-xs text-white/60">{tr("Recorded sales",lang)}</div><b className="mt-1 block">{money(totalRevenue)}</b></div></div></div></div></section><section className="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[["Recorded expenses",money(totalCost),Wallet],["Recorded sales",money(totalRevenue),TrendingUp],["Recorded difference",money(totalRevenue-totalCost),Calculator],["Crop cycles",String(crops.length),Sprout]].map(([t,v,I]:any)=><div className="card p-5" key={t}><div className="flex justify-between text-sm font-semibold text-[#71806c]">{tr(String(t),lang)}<I size={18} className="text-[#5a8e35]"/></div><div className="display mt-3 text-2xl font-extrabold">{v}</div><div className="muted mt-2 text-xs">{tr("Illustrative demo records",lang)}</div></div>)}</section><div className="mt-7 flex items-end justify-between"><div><h2 className="display text-xl font-extrabold">{tr("Your crop portfolio",lang)}</h2><p className="muted mt-1 text-sm">{tr("Crop-wise cost, sales and modeled season result.",lang)}</p></div><button className="btn2" onClick={()=>setModal("crop")}><Plus size={15} className="mr-1 inline"/> {tr("Add crop",lang)}</button></div><div className="mt-4 grid gap-4 xl:grid-cols-3">{cropCards}</div><p className="muted mt-3 text-xs">{tr("*Projected result uses entered expected yield × expected price − planned budget. It is an estimate, not a guarantee. Sample records are not real farmer data.",lang)}</p><div className="mt-5 grid gap-4 md:grid-cols-3">{[{name:"Weather & Crop AI",icon:CloudSun,desc:tr("Live forecast with explicit source and limits",lang)},{name:"Decision Simulator",icon:Calculator,desc:tr("Stress-test price, yield and costs",lang)},{name:"Farm Memory",icon:BookOpen,desc:tr("Export and restore your farm ledger",lang)}].map(x=><button key={x.name} className="card flex items-center gap-4 p-5 text-left" onClick={()=>setView(x.name as View)}><x.icon size={24} className="text-[#5a8e35]"/><div><b>{x.name}</b><p className="muted mt-1 text-xs">{x.desc}</p></div></button>)}</div></>}
{view==="My Crops"&&<><div className="mb-5 flex flex-wrap items-end justify-between"><div><h2 className="display text-2xl font-extrabold">{tr("My crop cycles",lang)}</h2><p className="muted mt-1 text-sm">{tr("Keep crop costs and sales separate.",lang)}</p></div><button className="btn" onClick={()=>setModal("crop")}><Plus size={15} className="mr-1 inline"/>{tr("Add crop",lang)}</button></div><div className="grid gap-4 xl:grid-cols-2">{cropCards}</div><button className="btn2 mt-5" onClick={()=>setModal("sale")}>{tr("Record a sale",lang)}</button></>}
{view==="Add Expense"&&<div className="grid gap-5 xl:grid-cols-[.8fr_1.2fr]"><section className="card p-5 md:p-7"><div className="label">{tr("Voice-first entry",lang)}</div><h2 className="display mt-2 text-2xl font-extrabold">{tr("Bolun Hishob · बोलून हिशोब",lang)}</h2><p className="muted mt-2 text-sm leading-6">{tr("Speak naturally, review the extracted fields, then confirm the record.",lang)}</p><div className="mt-5 rounded-xl bg-[#f1f6eb] p-4 text-sm"><b>{tr("Try:",lang)}</b> “मी सोयाबीनच्या खतासाठी २००० रुपये खर्च केले.”<p className="muted mt-1 text-xs">{tr("I spent ₹2,000 on soybean fertilizer.",lang)}</p></div><button className="btn mt-5 w-full" onClick={startVoice}><Mic size={16} className="mr-2 inline"/>{tr("Start voice capture",lang)}</button>{voice&&<p className="mt-3 rounded-xl bg-[#edf5e7] p-3 text-sm">{tr("Recognized:",lang)} {voice}</p>}<button className="btn2 mt-3 w-full" onClick={()=>setModal("expense")}>{tr("Enter or review expense",lang)}</button><p className="muted mt-3 text-xs">{tr("Speech recognition varies by browser and language. Manual entry always remains available.",lang)}</p></section><section className="card p-5"><div className="flex items-center justify-between"><div><h3 className="display text-lg font-extrabold">{tr("Expense ledger",lang)}</h3><p className="muted mt-1 text-xs">{expenses.length} {tr("records stored locally",lang)}</p></div></div><div className="mt-4 flex items-center gap-2 rounded-xl border px-3"><Search size={15}/><input className="w-full py-3 text-sm outline-none" placeholder={tr("Search expenses or crop…",lang)} value={query} onChange={e=>setQuery(e.target.value)}/></div>{table}</section></div>}
{view==="Profit & Loss"&&<><div className="grid gap-4 sm:grid-cols-3">{[["Sales",money(totalRevenue)],["Expenses",money(totalCost)],["Recorded difference",money(totalRevenue-totalCost)]].map(([a,b])=><div className="card p-5" key={a}><div className="muted text-sm">{tr(String(a),lang)}</div><div className="display mt-2 text-2xl font-extrabold">{b}</div></div>)}</div><div className="mt-5 grid gap-4 xl:grid-cols-2">{cropCards}</div><section className="card mt-5 p-5"><div className="flex flex-wrap justify-between gap-3"><h3 className="display text-lg font-extrabold">{tr("All expense transactions",lang)}</h3><input className="input !w-auto" placeholder={tr("Search…",lang)} value={query} onChange={e=>setQuery(e.target.value)}/></div>{table}<button className="btn2 mt-4" onClick={()=>setModal("sale")}>{tr("Record sale",lang)}</button></section></>}
{view==="Weather & Crop AI"&&<section className="card p-5 md:p-7"><span className="rounded-full bg-[#eaf3f7] px-3 py-1 text-xs font-bold text-[#437e9e]">{tr("LIVE WEATHER · OPEN-METEO",lang)}</span><h2 className="display mt-4 text-2xl font-extrabold">{tr("Weather for better decisions",lang)}</h2><p className="muted mt-2 max-w-2xl text-sm leading-6">{tr("Fetches a live forecast for Pune coordinates. Arbitrary village geocoding is not implemented in this prototype. Weather alone cannot determine crop suitability.",lang)}</p><button className="btn mt-5" disabled={loadingWeather} onClick={loadWeather}>{loadingWeather?tr("Loading forecast…",lang):tr("Load Pune forecast",lang)}</button>{weatherErr&&<p className="mt-4 rounded-xl bg-red-50 p-3 text-sm text-red-700">{weatherErr}</p>}{weather&&<><div className="mt-5 grid gap-4 md:grid-cols-[.7fr_1.3fr]"><div className="rounded-2xl bg-[#eaf3f7] p-5"><div className="text-sm font-bold text-[#437e9e]">{tr("Pune · current",lang)}</div><div className="display mt-2 text-5xl font-extrabold">{Math.round(weather.current.temperature_2m)}°C</div><div className="mt-3 space-y-2 text-sm">{tr("Feels like",lang)} {Math.round(weather.current.apparent_temperature)}°C<br/>{tr("Humidity",lang)} {weather.current.relative_humidity_2m}%<br/>{tr("Precipitation",lang)} {weather.current.precipitation} mm<br/>{tr("Wind",lang)} {weather.current.wind_speed_10m} km/h</div></div><div className="rounded-2xl border p-4"><b>{tr("Five-day forecast",lang)}</b><div className="mt-3 grid grid-cols-2 gap-3 sm:grid-cols-5">{weather.daily.time.map((d:string,i:number)=><div key={d} className="rounded-xl bg-[#f6f8f2] p-3"><div className="muted text-xs">{new Date(d+"T12:00:00").toLocaleDateString(lang==="Marathi"?"mr-IN":lang==="Hindi"?"hi-IN":"en-IN",{weekday:"short"})}</div><b className="mt-2 block">{Math.round(weather.daily.temperature_2m_max[i])}°</b><div className="muted text-xs">{Math.round(weather.daily.temperature_2m_min[i])}° {tr("low",lang)}</div><div className="mt-2 text-xs">{tr("Rain chance",lang)} {weather.daily.precipitation_probability_max[i]}%</div><div className="text-xs">{weather.daily.precipitation_sum[i]} mm</div></div>)}</div></div></div><p className="muted mt-3 text-xs">{tr("Source: Open-Meteo. Forecasts may change; this is not a field observation.",lang)}</p></>}</section>}
{view==="Decision Simulator"&&<section className="card p-5 md:p-7"><div className="label">{tr("What-if planner",lang)}</div><h2 className="display mt-2 text-2xl font-extrabold">{tr("What if yield or price drops?",lang)}</h2><p className="muted mt-2 text-sm">{tr("Adjust assumptions and see the modeled result update instantly.",lang)}</p><div className="mt-5 grid gap-5 lg:grid-cols-2"><div className="space-y-4"><div><label className="label">{tr("Crop",lang)}</label><select className="input mt-2" value={sim.cropId} onChange={e=>{const c=crops.find(x=>x.id===e.target.value)!;setSim(s=>({...s,cropId:c.id,yieldKg:String(c.yieldKg),price:String(c.price)}))}}>{crops.map(c=><option key={c.id} value={c.id}>{tr(c.name,lang)}</option>)}</select></div>{[{key:"yieldKg",label:"Expected yield (kg)",max:10000},{key:"price",label:"Expected price (₹/kg)",max:200},{key:"extra",label:"Additional cost (₹)",max:100000},{key:"yieldDrop",label:"Yield reduction (%)",max:100},{key:"priceDrop",label:"Price reduction (%)",max:100}].map(f=><div key={f.key}><div className="flex justify-between text-sm font-bold"><label>{tr(f.label,lang)}</label><span>{(sim as any)[f.key]}</span></div><input className="mt-2 w-full accent-[#477a32]" type="range" min="0" max={f.max} step={f.key==="price"?".5":f.key==="yieldKg"?"10":"1"} value={(sim as any)[f.key]} onChange={e=>setSim(s=>({...s,[f.key]:e.target.value}))}/></div>)}</div>{(()=>{const c=crops.find(x=>x.id===sim.cropId)!;const q=+sim.yieldKg*(1-+sim.yieldDrop/100),p=+sim.price*(1-+sim.priceDrop/100),costs=c.budget+ +sim.extra,result=q*p-costs;return <div className="rounded-3xl bg-[#23451f] p-6 text-white"><div className="text-xs font-bold tracking-widest text-[#c8ee8d]">{tr(c.name,lang)} · {tr("modeled scenario",lang)}</div><div className="mt-5 text-sm text-white/70">{tr("Estimated result",lang)}</div><div className="display mt-1 text-4xl font-extrabold">{money(result)}</div><div className="mt-5 space-y-3 border-t border-white/15 pt-4 text-sm">{[["Scenario yield",q.toLocaleString("en-IN")+" kg"],["Scenario price",money(p)+"/kg"],["Scenario revenue",money(q*p)],["Planned budget + extra costs",money(costs)]].map(([a,b])=><div className="flex justify-between gap-3" key={a}><span className="text-white/70">{a}</span><b>{b}</b></div>)}</div><p className="mt-5 rounded-xl bg-white/10 p-3 text-xs leading-5 text-white/75">{tr("Simplified scenario: revenue minus planned budget and extra costs. Existing recorded sales are not included. Validate yield, market price and budget locally.",lang)}</p></div>})()}</div></section>}
{view==="Market Prices"&&<section className="card p-5 md:p-7"><div className="label">{tr("Manual market quote",lang)}</div><h2 className="display mt-2 text-2xl font-extrabold">{tr("Compare your selling price",lang)}</h2><p className="muted mt-2 text-sm">{tr("Live mandi prices are not connected. Record a quote you received and verify its date, market and grade.",lang)}</p><div className="mt-5 grid gap-4 md:grid-cols-3"><div><label className="label">{tr("Crop",lang)}</label><select className="input mt-2" value={market.crop} onChange={e=>setMarket({...market,crop:e.target.value})}>{["Soybean","Onion","Pearl millet","Other"].map(x=><option key={x}>{tr(x,lang)}</option>)}</select></div><div><label className="label">{tr("Quote (₹/kg)",lang)}</label><input className="input mt-2" type="number" min="0" value={market.price} onChange={e=>setMarket({...market,price:e.target.value})}/></div><div><label className="label">{tr("Market / source note",lang)}</label><input className="input mt-2" value={market.market} onChange={e=>setMarket({...market,market:e.target.value})} placeholder={tr("Market name, date…",lang)}/></div></div><button className="btn mt-4" onClick={()=>{if(!market.price||+market.price<0){tell(tr("Enter a valid quote.",lang));return}tell(tr("Manual quote: ",lang)+tr(market.crop,lang)+" "+tr(" at ",lang)+" "+money(+market.price)+"/kg"+(market.market?" · "+market.market:"")+" . "+tr("Not a live mandi rate.",lang))}}>{tr("Save quote note",lang)}</button><div className="mt-4 rounded-xl bg-[#fff7e8] p-4 text-sm text-[#8c6a29]">{tr("Manual quote only — this is not an official or live market price.",lang)}</div></section>}
{view==="Farm Memory"&&<section className="card p-5 md:p-7"><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="display text-2xl font-extrabold">{tr("Farm memory & backup",lang)}</h2><p className="muted mt-1 text-sm">{tr("Stored in this browser. Export before changing device.",lang)}</p></div><button className="btn" onClick={()=>{const a=document.createElement("a"),url=URL.createObjectURL(new Blob([JSON.stringify({crops,expenses,sales},null,2)],{type:"application/json"}));a.href=url;a.download="shetkarimitra-backup.json";a.click();URL.revokeObjectURL(url);tell(tr("Backup exported.",lang))}}><Download size={15} className="mr-2 inline"/>{tr("Export backup",lang)}</button></div><div className="mt-5 grid gap-4 sm:grid-cols-3">{[["Crop cycles",crops.length],["Expense records",expenses.length],["Sales records",sales.length]].map(([a,b])=><div className="rounded-xl bg-[#f6f8f2] p-4" key={a as string}><div className="muted text-sm">{tr(String(a),lang)}</div><div className="display mt-1 text-2xl font-extrabold">{b}</div></div>)}</div><label className="btn2 mt-5 inline-block cursor-pointer">{tr("Import backup",lang)}<input type="file" accept="application/json" className="hidden" onChange={async e=>{const f=e.target.files?.[0];if(!f)return;try{const d=JSON.parse(await f.text());if(!Array.isArray(d.crops)||!Array.isArray(d.expenses)||!Array.isArray(d.sales))throw Error();setCrops(d.crops);setExpenses(d.expenses);setSales(d.sales);tell(tr("Backup restored.",lang))}catch{tell(tr("Invalid backup file.",lang))}e.currentTarget.value=""}}/></label><button className="btn2 ml-3 mt-5" onClick={()=>{if(confirm(tr("Reset all browser records to illustrative demo data?",lang))){setCrops(demoCrops);setExpenses(demoExpenses);setSales(demoSales);tell(tr("Demo data restored.",lang))}}}>{tr("Reset demo data",lang)}</button><div className="mt-5">{cropCards}</div></section>}</main><footer className="border-t border-[#e5eadf] px-5 py-5 text-xs text-[#8a9684]">ShetkariMitra AI · {tr("Illustrative demo records",lang)} · {tr("Demo records are illustrative · Not agricultural or financial guarantees.",lang)}</footer></div>
{modal&&<div className="fixed inset-0 z-50 flex items-center justify-center bg-[#152513]/50 p-4" onMouseDown={e=>{if(e.target===e.currentTarget)setModal(null)}}><div className="max-h-[90vh] w-full max-w-lg overflow-y-auto rounded-3xl bg-white p-6 shadow-2xl"><div className="flex items-center justify-between"><h2 className="display text-xl font-extrabold">{tr(modal==="expense"?"Record expense":modal==="crop"?"Add crop cycle":"Record crop sale",lang)}</h2><button onClick={()=>setModal(null)}>✕</button></div>{modal==="expense"&&<div className="mt-5 space-y-4"><div><label className="label">{tr("Crop",lang)}</label><select className="input mt-2" value={ef.cropId} onChange={e=>setEf({...ef,cropId:e.target.value})}>{crops.map(c=><option value={c.id} key={c.id}>{tr(c.name,lang)}</option>)}</select></div><div><label className="label">{tr("Amount (₹)",lang)}</label><input className="input mt-2" type="number" min=".01" value={ef.amount} onChange={e=>setEf({...ef,amount:e.target.value})} placeholder="2000"/></div><div><label className="label">{tr("Category",lang)}</label><select className="input mt-2" value={ef.category} onChange={e=>setEf({...ef,category:e.target.value})}>{categories.map(c=><option key={c}>{tr(c,lang)}</option>)}</select></div><div><label className="label">{tr("Description",lang)}</label><textarea className="input mt-2" rows={2} value={ef.description} onChange={e=>setEf({...ef,description:e.target.value})}/></div><div><label className="label">{tr("Date",lang)}</label><input className="input mt-2" type="date" value={ef.date} onChange={e=>setEf({...ef,date:e.target.value})}/></div><button className="btn w-full" onClick={saveExpense}><CheckCircle2 size={15} className="mr-2 inline"/>{tr("Confirm and save",lang)}</button></div>}{modal==="crop"&&<div className="mt-5 space-y-4"><div><label className="label">{tr("Crop name",lang)}</label><input className="input mt-2" value={cf.name} onChange={e=>setCf({...cf,name:e.target.value})} placeholder={tr("e.g. Cotton",lang)}/></div><div className="grid grid-cols-2 gap-3">{[{key:"area",label:"Area (acres)"},{key:"budget",label:"Budget (₹)"},{key:"yieldKg",label:"Expected yield (kg)"},{key:"price",label:"Expected price (₹/kg)"}].map(f=><div key={f.key}><label className="label">{tr(f.label,lang)}</label><input className="input mt-2" type="number" min="0" value={(cf as any)[f.key]} onChange={e=>setCf({...cf,[f.key]:e.target.value})}/></div>)}</div><div><label className="label">{tr("Season",lang)}</label><input className="input mt-2" value={cf.season} onChange={e=>setCf({...cf,season:e.target.value})}/></div><button className="btn w-full" onClick={addCrop}>{tr("Create crop cycle",lang)}</button></div>}{modal==="sale"&&<div className="mt-5 space-y-4"><div><label className="label">{tr("Crop",lang)}</label><select className="input mt-2" value={sf.cropId} onChange={e=>setSf({...sf,cropId:e.target.value})}>{crops.map(c=><option value={c.id} key={c.id}>{tr(c.name,lang)}</option>)}</select></div><div className="grid grid-cols-2 gap-3"><div><label className="label">{tr("Quantity sold (kg)",lang)}</label><input className="input mt-2" type="number" min=".01" value={sf.quantity} onChange={e=>setSf({...sf,quantity:e.target.value})}/></div><div><label className="label">{tr("Price (₹/kg)",lang)}</label><input className="input mt-2" type="number" min="0" value={sf.price} onChange={e=>setSf({...sf,price:e.target.value})}/></div></div><button className="btn w-full" onClick={addSale}>{tr("Save sale",lang)}</button></div>}</div></div>}{notice&&<div role="status" className="fixed bottom-5 right-5 z-[70] max-w-sm rounded-2xl bg-[#23451f] px-5 py-3 text-sm font-bold text-white shadow-xl">{tr(notice,lang)}</div>}</div>}